function Detail({ value, sources, names, field = "" }: { value: unknown; sources: DefinitionSource[]; names: Map<string, string>; field?: string }) {
  if (value === null || value === undefined || value === "") return <span className="subtle">未知 / 尚未记录</span>;
  if (typeof value === "boolean") return <span>{value ? "是" : "否"}</span>;
  if (typeof value === "number") return <span>{value}</span>;
  if (typeof value === "string") return <span className="whitespace-pre-wrap [overflow-wrap:anywhere]">{names.get(value) ?? (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value) ? "固定身份，名称当前待核对" : enumFields.has(field) ? states[value] ?? professionalRuleNames[value as keyof typeof professionalRuleNames] ?? startControlNames[value as keyof typeof startControlNames] ?? value : value)}</span>;
  if (Array.isArray(value) && (field === "material_holds" || field === "resource_reservations")) return <span>已保存 {value.length} 条{field === "material_holds" ? "物料保留记录" : "资源占用记录"}</span>;
  if (Array.isArray(value)) return value.length ? <div className="space-y-3">{value.map((row, index) => <article key={index} className="rounded-lg border border-border p-3"><Detail value={row} sources={sources} names={names} field={field}/></article>)}</div> : <span className="subtle">本次没有列出，不能据此推定已知</span>;
  if (!startRecord(value)) return null;
  if (typeof value.artifact_id === "string" && typeof value.quote === "string" && typeof value.line === "number") return <References refs={[value as unknown as DefinitionReference]} sources={sources}/>;
  if (typeof value.authorized === "boolean" && Array.isArray(value.roles) && Array.isArray(value.fact_refs)) return <Authority value={value as unknown as ProfessionalAuthority}/>;
  if (typeof value.kind === "string" && typeof value.id === "string" && typeof value.revision === "number" && !Object.keys(value).some(key => fields[key] && !["kind", "revision"].includes(key))) return <p>{states[value.kind] ?? "固定业务依据"} · v{value.revision}</p>;
  return <dl className="space-y-3">{Object.entries(value).filter(([key]) => !hidden.has(key) && (fields[key] || key.endsWith("_id") || key.endsWith("_revision"))).map(([key, row]) => <div key={key}><dt className="subtle mb-1">{fields[key] ?? (key.endsWith("_revision") ? "固定记录版本" : "固定关联记录")}</dt><dd className="text-sm"><Detail value={row} sources={sources} names={names} field={key}/></dd></div>)}</dl>;
}
function SavedReservations({ value }: { value: unknown }) { const record = startRecord(value) ? value : {}; const count = (records: unknown) => Array.isArray(records) ? `${records.length} 条` : "条数待核对"; return <p className="rounded-lg border border-border p-3 text-sm">随本次开工保存：物料保留 {count(record.material_holds)}、资源占用 {count(record.resource_reservations)}。记录已保存，条数不代表物料用量或资源数量。</p>; }
function ScopeReading({ scope }: { scope: ExecutionAssessment["execution_scope"] }) { return <dl className="grid gap-3 text-sm sm:grid-cols-2"><div><dt className="subtle">仅限用途</dt><dd className="whitespace-pre-wrap [overflow-wrap:anywhere]">{scope.purpose}</dd></div><div><dt className="subtle">明确数量</dt><dd className="[overflow-wrap:anywhere]">{scope.quantity} {scope.unit}</dd></div><div><dt className="subtle">明确场地</dt><dd className="[overflow-wrap:anywhere]">{scope.site}</dd></div><div><dt className="subtle">固定窗口与原时区</dt><dd className="[overflow-wrap:anywhere]">{scope.window_start}<br/>{scope.window_end}<br/>{scope.window_timezone}</dd></div></dl>; }
function AssessmentReading({ assessment, sources, names }: { assessment: ExecutionAssessment; sources: DefinitionSource[]; names: Map<string, string> }) { return <section className="space-y-4"><h4 className="font-semibold">固定执行准备评估 v{assessment.revision}</h4><ScopeReading scope={assessment.execution_scope}/><p className="rounded-lg border border-primary p-3 text-sm">{states[assessment.result.state] ?? "准备结论尚待核对"}。仅描述上述固定范围，不是量产放行，也不自动建立开工事实。</p><p className="text-sm">物料与资源操作准备：{states[String(assessment.result.operational_state ?? assessment.result.state)] ?? "未知"}；专业适用和执行限制仍分别具名核对。</p><p className="subtle">{assessment.is_current ? "本轮当前评估" : "固定历史评估"} · {assessment.source_status === "current" ? "固定来源当前有效" : "固定来源或事实需重核，历史结论不能沿用"}<br/>计算记录 {time(assessment.created_at)} · 新动作核对当前版本与水位</p>{assessment.result.nature === "synthetic" && <p className="text-sm text-primary">此评估含合成事实，仅供明确的本地验证，不能作为生产启用依据。</p>}<div className="space-y-3">{assessment.result.checks.map((check, index) => <article key={index} className="space-y-2 rounded-lg border border-border p-3"><h5 className="text-sm font-medium">{typeof check.label === "string" ? check.label : ({ material: "材料齐套与品质限制", materials: "材料齐套与品质限制", resource: "资源容量与资格", resources: "资源容量与资格", engineering: "工程适用范围", manufacturing: "制造适用范围", source: "固定来源有效性", sources: "固定来源有效性", product_verification: "型号与验证专业适用", manufacturing_applicability: "制造专业适用", delivery_applicability: "产出处置专业适用", binding: "固定计划与需求范围", authority: "可信操作事实" } as Record<string, string>)[String(check.dimension)] ?? "本用途必需检查"} · {states[String(check.status)] ?? "待核对"}</h5><p className="text-sm whitespace-pre-wrap [overflow-wrap:anywhere]">{typeof check.detail === "string" ? check.detail : typeof check.message === "string" ? check.message : "事实尚未完整取得，不默认通过。"}</p>{typeof check.recovery_action === "string" && <p className="text-sm whitespace-pre-wrap">下一步：{check.recovery_action}</p>}{typeof check.code === "string" && <details className="text-xs"><summary className="cursor-pointer subtle">核对标识</summary><p className="[overflow-wrap:anywhere]">{check.code}</p></details>}</article>)}{!assessment.result.checks.length && <p className="subtle">尚未取得逐条准备检查，不能自行判为已就绪。</p>}</div><details><summary className="cursor-pointer text-sm font-medium">固定物料、资源与受控事实 · 只读</summary><div className="mt-3 space-y-3"><Detail value={assessment.result.fact_refs} sources={sources} names={names}/><Detail value={assessment.result.operational_facts ?? assessment.result.facts ?? assessment.input_snapshot} sources={sources} names={names}/><Detail value={assessment.result.coverage} sources={sources} names={names}/><Detail value={assessment.result.resources} sources={sources} names={names}/></div><p className="subtle mt-3">本页不能自行登记可用库存、校准、资格或专业放行。可信导入事实仍受用途、版本和有效期限制。</p></details></section>; }
function RefChoices({ refs, chosen, sources, onChange }: { refs: DefinitionReference[]; chosen: DefinitionReference[]; sources: DefinitionSource[]; onChange: (refs: DefinitionReference[]) => void }) { return <fieldset className="space-y-2 rounded-lg border border-border p-3"><legend className="px-1 text-sm font-medium">本次具名决定采用的精确原文</legend>{refs.map(ref => <label key={startReferenceKey(ref)} className="flex items-start gap-2 text-sm"><input className="!mt-1 !w-auto shrink-0" type="checkbox" checked={chosen.some(row => startReferenceKey(row) === startReferenceKey(ref))} onChange={event => onChange(event.target.checked ? [...chosen, ref] : chosen.filter(row => startReferenceKey(row) !== startReferenceKey(ref)))}/><span className="[overflow-wrap:anywhere]">{sources.find(row => row.id === ref.artifact_id)?.title ?? "固定原文"} · v{ref.expected_revision} · 第 {ref.line} 行<br/>{ref.quote}</span></label>)}{!refs.length && <p className="subtle">请先在精确原文区选择实际依据。</p>}</fieldset>; }
